"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4215],{34215:i=>{i.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"servisy","title":"Справочник. Сервисы и источники: Где это сделать и откуда цифры, одной таблицей","sourceFingerprint":"83e2fdb5cf8885645e4bcc0055fa063b6156b896cb268680c59ad75b1f280d70","blocks":[{"id":"b001","markdown":"## Сервисы и источники"},{"id":"b002","markdown":"Где это сделать и откуда цифры, одной таблицей"},{"id":"b003","markdown":"Все сайты и источники из уроков на одной странице: где сделать то, что советует курс, и откуда взяты цифры. Открывай их по этим ссылкам или из закладок, а не из поиска и рекламы: поддельные сайты встречаются часто."},{"id":"b004","markdown":"### Где это сделать"},{"id":"b005","markdown":"Здесь делается то, что советуют уроки: самозапреты, кредитная история, вычеты."},{"id":"b006","markdown":"- Госуслуги gosuslugi.ru Кредитная история, самозапрет на кредиты и на SIM-карты, заявление в полицию, вычеты. Здесь же включается вход с подтверждением. Урок 4\\n- Личный кабинет налогоплательщика lkfl2.nalog.ru Предзаполненные заявления на вычет и декларация 3-НДФЛ. Вход через Госуслуги. Урок 10\\n- Социальный фонд sfr.gov.ru Сюда, как и через Госуслуги, подают заявление на семейную налоговую выплату. Урок 10\\n- АСВ asv.org.ru Агентство по страхованию вкладов: список банков в системе. Проверить, застрахованы ли вклады, лимит 1,4 млн ₽ на человека в одном банке. Урок 6"},{"id":"b007","markdown":"### Откуда цифры"},{"id":"b008","markdown":"Ставки и законы меняются. Свежие значения смотри у первоисточника."},{"id":"b009","markdown":"- Банк России cbr.ru Ключевая ставка, средняя максимальная ставка по вкладам 10 крупнейших банков, ПДН, статистика мошенничества, прогнозы аналитиков. Урок 9\\n- Росстат rosstat.gov.ru Инфляция и средняя зарплата, на которых построены примеры в уроках. Урок 8\\n- ФНС nalog.gov.ru Ставки НДФЛ, вычеты и их лимиты. Урок 10\\n- ОКБ bki-okb.ru Объединённое кредитное бюро: средняя полная стоимость кредитов, в том числе по кредитным картам. Урок 4\\n- Russian Field russianfield.com Опрос о сбережениях: у скольких их нет и на сколько месяцев хватит запаса. Урок 1\\n- НАФИ nafi.ru Аналитический центр, вместе с НИФИ Минфина считает, сколько людей живут без накоплений. Урок 1\\n- НИФИ Минфина nifi.ru Научно-исследовательский финансовый институт Минфина. Второй источник оценки \xabбез накоплений\xbb. Урок 1"},{"id":"b010","markdown":"### Дополнительный официальный сервис"},{"id":"b011","markdown":"Центральный каталог кредитных историй Банка России помогает узнать, в каких бюро хранится ваша кредитная история. Проверяйте сведения через официальный сервис и не вводите персональные данные на рекламных копиях."},{"id":"b012","markdown":"Банки здесь не рекламируются: выбирайте их по правилам урока 9, а не по партнёрской ссылке."}],"terms":[],"quizzes":[],"officialSources":[{"id":"gosuslugi","title":"Госуслуги","url":"https://www.gosuslugi.ru/","description":"Кредитная история, самозапрет на кредиты и SIM-карты, заявления и защищённый вход."},{"id":"tax-cabinet","title":"Личный кабинет налогоплательщика","url":"https://lkfl2.nalog.ru/","description":"Предзаполненные заявления на вычет и декларация 3-НДФЛ; вход через Госуслуги."},{"id":"social-fund","title":"Социальный фонд России","url":"https://sfr.gov.ru/","description":"Условия и подача заявления на семейную налоговую выплату."},{"id":"deposit-insurance","title":"Агентство по страхованию вкладов","url":"https://www.asv.org.ru/","description":"Проверка участия банка в страховании вкладов и условий страхового возмещения."},{"id":"central-bank","title":"Банк России","url":"https://www.cbr.ru/","description":"Ключевая ставка, мониторинг ставок по вкладам, долговая нагрузка и защита от мошенничества."},{"id":"rosstat","title":"Росстат","url":"https://rosstat.gov.ru/","description":"Официальная статистика инфляции, цен и начисленной заработной платы."},{"id":"tax-service","title":"Федеральная налоговая служба","url":"https://www.nalog.gov.ru/","description":"Действующие ставки НДФЛ, виды вычетов, лимиты и требования к документам."},{"id":"credit-bureau","title":"Объединённое кредитное бюро","url":"https://bki-okb.ru/","description":"Кредитная история и первичные данные бюро о полной стоимости кредитов."},{"id":"russian-field","title":"Russian Field","url":"https://russianfield.com/","description":"Первичный источник опроса о наличии накоплений и запасе средств; это исследовательская организация, не госрегулятор."},{"id":"nafi","title":"Аналитический центр НАФИ","url":"https://nafi.ru/","description":"Первичные исследования финансового поведения и сбережений; это аналитический центр, не госрегулятор."},{"id":"nifi","title":"Научно-исследовательский финансовый институт","url":"https://www.nifi.ru/","description":"Исследования финансовой грамотности и сбережений; проверяйте даты и методику опросов."},{"id":"credit-catalogue","title":"Центральный каталог кредитных историй","url":"https://www.cbr.ru/ckki/","description":"Официальный сервис Банка России: определить бюро, в которых хранится кредитная история."}]}')}}]);